State.variables.player.flags.frank_bedroom_first_done = false;
return JSON.stringify({
  stage: State.variables.player.core_traits.npc_frank_stage,
  invited: State.variables.player.flags.frank_invited_to_bedroom,
  consummated: State.variables.player.flags.frank_bedroom_first_done,
  corruption: State.variables.player.core_traits.corruption
