var SC = window.SugarCube || window.parent && window.parent.SugarCube;
var V = SC && SC.State && SC.State.variables;
if (!V) return 'NO STATE - SC keys: ' + Object.keys(window).filter(function(k){return k.toLowerCase().indexOf('sugar')>-1}).join(',');
V.player.core_traits.npc_frank_stage = 4;
V.player.core_traits.corruption = 30;
V.player.flags.frank_invited_to_bedroom = true;
V.player.flags.frank_office_first_sex_done = true;
