V.player.flags.frank_restrict_declared = true;
V.player.flags.arrived_at_franks = true;
V.player.flags.frank_bedroom_first_done = false;
return JSON.stringify({
  stage: V.player.core_traits.npc_frank_stage,
  invited: V.player.flags.frank_invited_to_bedroom,
  consummated: V.player.flags.frank_bedroom_first_done,
  corruption: V.player.core_traits.corruption
});

var SC = window.SugarCube;
var V = SC.State.variables;
return JSON.stringify({
  state_keys: Object.keys(V),
  player_keys: V.player ? Object.keys(V.player) : 'no player',
  flags_type: typeof V.flags,
  has_flags_root: !!V.flags
});

var V = window.SugarCube.State.variables;
return JSON.stringify({
  state_keys: Object.keys(V),
  player_keys: V.player ? Object.keys(V.player) : 'no player',
